import { describe, it, expect } from "vitest";
import { resolve, dirname } from "path";
import { readFileSync } from "fs";
import { fileURLToPath } from "url";
import * as zarr from "zarrita";
import type { AsyncReadable } from "../src/types.js";
import { HdfStore } from "../src/index.js";
import { File as Hdf5File } from "../src/jsfive/high-level.js";

const fixturesDir = resolve(dirname(fileURLToPath(import.meta.url)), "fixtures");

/** Generated by test/fixtures/many_attributes.py from h5py reads. */
const expected: Record<string, Record<string, Record<string, unknown>>> = JSON.parse(
  readFileSync(resolve(fixturesDir, "many_attributes.expected.json"), "utf-8")
);

class MemorySource implements AsyncReadable {
  private data: Uint8Array;
  constructor(fixtureName: string) {
    this.data = new Uint8Array(readFileSync(resolve(fixturesDir, fixtureName)));
  }
  async get(): Promise<Uint8Array> {
    throw new Error("unexpected get");
  }
  async getRange(_key: string, range: { offset: number; length: number } | { suffixLength: number }) {
    if (!("offset" in range)) throw new Error("unexpected suffix read");
    return this.data.slice(range.offset, range.offset + range.length);
  }
}

describe("many attributes", () => {
  // v1: object headers spanning many continuation blocks (with zero-size NIL messages).
  // v2: dense attribute storage (fractal heap + attribute name index B-tree).
  for (const version of ["v1", "v2"]) {
    const fixture = `many_attributes_${version}.h5`;

    it(`${version}: every attribute is read, with h5py's values`, async () => {
      const store = await HdfStore.fromStore(new MemorySource(fixture));
      const root = zarr.root(store);
      const group = await zarr.open(root.resolve("group"), { kind: "group" });
      expect(group.attrs).toEqual(expected[version].group);
      const data = await zarr.open(root.resolve("group/data"), { kind: "array" });
      expect(data.attrs).toEqual(expected[version]["group/data"]);
      expect(Object.keys(data.attrs)).toHaveLength(42);
      const values = (await zarr.get(data)) as { data: Float64Array };
      expect(Array.from(values.data)).toEqual(Array.from({ length: 1000 }, (_, i) => i));
    });

    it(`${version}: object headers parse every declared message`, async () => {
      const file = await Hdf5File.create(new MemorySource(fixture));
      for (const path of ["group", "group/data"]) {
        const node = await file.get(path);
        const declared = node._dataobjects._header.get("total_header_messages");
        if (declared !== undefined) expect(node._dataobjects.msgs.length).toBe(declared);
      }
    });
  }
});
